insert into public.content_items (date, topic, hook, key_points, cta, target_niche, status, platform, notes) values
  (current_date, 'Чому українському бізнесу в Польщі потрібна довіра', 'Люди не купують у логотипу.', 'Довіра, обличчя, історія, регулярна присутність.', 'Напишіть Hugo, якщо бізнесу потрібна медійність.', 'Усі ніші', 'Підготувати', 'Instagram', 'Зняти як короткий монолог.'),
  (current_date + interval '1 day', 'Люди купують не у бізнесу, а у людини', 'Ваш продукт можуть скопіювати, вашу історію ні.', 'Власник, цінності, шлях, доказ експертності.', 'Покажемо людину за бізнесом.', 'Експерти', 'Ідея', 'TikTok', ''),
  (current_date + interval '2 days', 'Я не SMM, я медіаплатформа', 'Це не про пости. Це про довіру.', 'Журналістська подача, авторська платформа, історія бізнесу.', 'Поговорімо про формат Hugo.', 'Послуги', 'Ідея', 'Facebook', ''),
  (current_date + interval '3 days', 'Як показати людину за бізнесом', 'Коли клієнт бачить людину, бар’єр падає.', 'Обличчя, голос, шлях, доказ, контекст.', 'Покажемо ваш бізнес через людину.', 'Усі ніші', 'Ідея', 'YouTube Shorts', ''),
  (current_date + interval '4 days', 'Чому реклама без довіри не працює', 'Охоплення без довіри не продає.', 'Довіра передує продажу, медійність підсилює рекомендації.', 'Зробимо бізнес помітним і зрозумілим.', 'Усі ніші', 'Ідея', 'Telegram', '');
insert into public.templates (title, category, body) values
  ('Перше повідомлення для бізнесу', 'Перше повідомлення', 'Вітаю! Я Hugo, незалежний журналіст і автор Hugo Media Group. Побачив ваш бізнес і думаю, що його можна показати не просто як послугу, а як історію людини за бізнесом.'),
  ('Follow-up після першого контакту', 'Follow-up 1', 'Вітаю! Повертаюся до нашого контакту. Моя ідея проста: зробити ваш бізнес видимішим через довіру, історію і живу медійну подачу.'),
  ('Відповідь “скиньте деталі”', 'Відповідь “скиньте деталі”', 'Звісно. У мене є кілька форматів: медійний візит, місячна медіасерія або повна присутність. Сенс у тому, щоб показати людину за бізнесом і підсилити довіру.'),
  ('Відповідь “дорого”', 'Відповідь “дорого”', 'Розумію. Тут оплата не за пост, а за медійну довіру: підготовка, зйомка, подача, історія і матеріали, які бізнес може використовувати далі.'),
  ('Повернення через 30 днів', 'Повідомлення для повернення через 30 днів', 'Вітаю! Домовлялися повернутися до теми пізніше. Якщо зараз актуально підсилити довіру до бізнесу, можу запропонувати короткий формат медійного візиту.');
